<?php
declare(strict_types=1);
final class ManualMethods
{
    public function __construct(private PDO $db){}
    public function config():array{$s=$this->db->query("SELECT data,version FROM jingo_settings WHERE id='manual-payments'");$r=$s->fetch(PDO::FETCH_ASSOC);return $r?['version'=>(int)$r['version'],'methods'=>json_decode($r['data'],true,512,JSON_THROW_ON_ERROR)['methods']]:['version'=>0,'methods'=>[['id'=>'PAY_LATER','name'=>'Thanh toán sau','englishName'=>'Pay later','instructions'=>'Nhân viên sẽ liên hệ xác nhận và hướng dẫn thanh toán.','englishInstructions'=>'Our staff will contact you to confirm the booking and arrange payment.','enabled'=>true]]];}
    public function read():array{return $this->config()['methods'];}
    public function active():array{$out=[];foreach($this->read() as $m)if($m['enabled'])$out[]=array_intersect_key($m,array_flip(['id','name','englishName','instructions','englishInstructions']));return $out;}
    public function select(string $id):array{foreach($this->active() as $m)if($m['id']===$id){$m['englishName']=(array_key_exists('englishName',$m)?$m['englishName']:'')?:$m['name'];$m['englishInstructions']=(array_key_exists('englishInstructions',$m)?$m['englishInstructions']:'')?:(array_key_exists('instructions',$m)?$m['instructions']:'');return $m;}throw new HttpError(400,'Phương thức thanh toán đã tắt hoặc không tồn tại. Vui lòng chọn lại.');}
    private static function text(mixed $v,int $min,int $max):string{if(!is_string($v)||str_contains($v,"\0"))throw new HttpError(400,'Tên hoặc hướng dẫn không hợp lệ.');$v=preg_replace('/^[\s\x{FEFF}]+|[\s\x{FEFF}]+$/u','',$v);$n=$v===null?-1:strlen(mb_convert_encoding($v,'UTF-16LE','UTF-8'))/2;if($n<$min||$n>$max)throw new HttpError(400,'Tên tối đa 100, hướng dẫn tối đa 600 ký tự.');return $v;}
    public function save(array $in,string $actor):array
    {
        if(count($in)!==2||array_diff(array_keys($in),['version','methods'])||!is_int($in['version'] ?? null)||$in['version']<0||$in['version']>2147483646||!is_array($in['methods'] ?? null)||!array_is_list($in['methods'])||count($in['methods'])>20)throw new HttpError(400,'Kiểm tra phương thức thanh toán (tối đa 20 mục).');
        $methods=[];$ids=[];foreach($in['methods'] as $m){if(!is_array($m)||array_diff(array_keys($m),['id','name','englishName','instructions','englishInstructions','enabled'])||!is_string($m['id'] ?? null)||!preg_match('/^(?:CASH|PAY_LATER|MANUAL_[a-zA-Z0-9_-]{1,60})$/D',$m['id'])||isset($ids[$m['id']])||!is_bool($m['enabled'] ?? null))throw new HttpError(400,'Mã phương thức không hợp lệ hoặc bị trùng.');$ids[$m['id']]=true;$methods[]=['id'=>$m['id'],'name'=>self::text($m['name'] ?? null,1,100),'englishName'=>self::text(array_key_exists('englishName',$m)?$m['englishName']:'',0,100),'instructions'=>self::text(array_key_exists('instructions',$m)?$m['instructions']:'',0,600),'englishInstructions'=>self::text(array_key_exists('englishInstructions',$m)?$m['englishInstructions']:'',0,600),'enabled'=>$m['enabled']];}
        $this->db->exec('SET TRANSACTION ISOLATION LEVEL READ COMMITTED');$this->db->beginTransaction();try{
            if(!$this->db->query("SELECT id FROM jingo_catalog_locks WHERE id='catalog' FOR UPDATE")->fetchColumn())throw new HttpError(503,'Chưa cài khóa danh mục.');$old=$this->config();if($old['version']!==$in['version'])throw new HttpError(409,'Phương thức vừa thay đổi. Tải lại trước khi lưu.');
            $q=$this->db->prepare("INSERT INTO jingo_settings(id,data,version) VALUES ('manual-payments',?,?) ON DUPLICATE KEY UPDATE data=VALUES(data),version=VALUES(version)");$q->execute([json_encode(['methods'=>$methods],JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),$in['version']+1]);$q=$this->db->prepare('INSERT INTO jingo_audit(id,admin_id,action,entity_id) VALUES (?,?,?,?)');$q->execute([bin2hex(random_bytes(16)),$actor,'payment.manual-methods.save','manual-payments']);$this->db->commit();return ['version'=>$in['version']+1,'methods'=>$methods];
        }catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
    }
}
